define([],function(){"use strict";function init(descriptions){var select=document.getElementById("id_categoryid");var description=document.getElementById("kopere_dashboard-requests-category-description");if(!select||!description){return}select.insertAdjacentElement("afterend",description);function updateDescription(){var text=Object.prototype.hasOwnProperty.call(descriptions,select.value)?descriptions[select.value]:"";description.textContent=text||""}select.addEventListener("change",updateDescription);updateDescription()}return{init:init}});
